package docsdrift

import (
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

// The bug fix ledger is generated by automation/ci/bugledger from the git history. This test needs no history, so the docs job, which checks out one commit, still gates the committed files: every entry has the fields the ledger promises, every test an entry names exists, and the public page lists every entry.

type ledgerEntry struct {
	ID         string   `json:"id"`
	Title      string   `json:"title"`
	Symptom    string   `json:"symptom"`
	Impact     string   `json:"userImpact"`
	Platform   string   `json:"platform"`
	Class      string   `json:"class"`
	Divergence string   `json:"divergence"`
	RemoveWhen string   `json:"removeWhen"`
	FixedIn    string   `json:"fixedIn"`
	Commits    []any    `json:"commits"`
	Tests      []string `json:"tests"`
}

type ledgerFile struct {
	Since       string        `json:"since"`
	Entries     []ledgerEntry `json:"entries"`
	Divergences []struct {
		ID    string `json:"id"`
		Entry string `json:"entry"`
	} `json:"divergences"`
}

var goTestDecl = regexp.MustCompile(`(?m)^func ((?:Test|Fuzz)[A-Za-z0-9_]*)\(`)

func readBugLedger(t *testing.T) (ledgerFile, string) {
	t.Helper()
	data, err := os.ReadFile("../../docs/bug-ledger.json")
	if err != nil {
		t.Fatalf("%v; run `make bug-ledger`", err)
	}
	var l ledgerFile
	if err := json.Unmarshal(data, &l); err != nil {
		t.Fatalf("docs/bug-ledger.json: %v", err)
	}
	page, err := os.ReadFile("../../docs/site/docs/bug-ledger.md")
	if err != nil {
		t.Fatal(err)
	}
	return l, string(page)
}

func TestBugLedgerEntriesAreComplete(t *testing.T) {
	l, _ := readBugLedger(t)
	if l.Since == "" || len(l.Entries) == 0 {
		t.Fatal("the bug ledger is empty; the gate would pass vacuously")
	}
	seen := map[string]bool{}
	for _, e := range l.Entries {
		if seen[e.ID] {
			t.Errorf("duplicate ledger ID %s", e.ID)
		}
		seen[e.ID] = true
		for field, value := range map[string]string{"title": e.Title, "symptom": e.Symptom, "userImpact": e.Impact, "platform": e.Platform, "fixedIn": e.FixedIn} {
			if strings.TrimSpace(value) == "" {
				t.Errorf("%s has no %s", e.ID, field)
			}
		}
		switch e.Class {
		case "own", "pi-port":
		case "ahead-of-pi":
			if e.Divergence == "" || e.RemoveWhen == "" {
				t.Errorf("%s is fixed ahead of Pi and needs its divergence number and the condition that removes the difference", e.ID)
			}
		default:
			t.Errorf("%s has the unknown class %q", e.ID, e.Class)
		}
		if len(e.Commits) == 0 && !strings.Contains(e.ID, "pending") {
			t.Errorf("%s names no fix commit", e.ID)
		}
	}
}

func TestBugLedgerTestsExist(t *testing.T) {
	l, _ := readBugLedger(t)
	checked := 0
	for _, e := range l.Entries {
		for _, ref := range e.Tests {
			path, name, hasName := strings.Cut(ref, "::")
			data, err := os.ReadFile(filepath.Join("../..", filepath.FromSlash(path)))
			if err != nil {
				t.Errorf("%s names the test %s, but its file is missing; run `make bug-ledger`", e.ID, ref)
				continue
			}
			checked++
			if !hasName {
				continue
			}
			found := false
			for _, m := range goTestDecl.FindAllSubmatch(data, -1) {
				found = found || string(m[1]) == name
			}
			if !found {
				t.Errorf("%s names the test %s, which its file no longer declares; run `make bug-ledger`", e.ID, ref)
			}
		}
	}
	if checked == 0 {
		t.Fatal("no ledger entry names a test; the check would pass vacuously")
	}
}

func TestBugLedgerPageListsEveryEntry(t *testing.T) {
	l, page := readBugLedger(t)
	for _, e := range l.Entries {
		if !strings.Contains(page, "### "+e.ID+"\n") {
			t.Errorf("docs/site/docs/bug-ledger.md has no section for %s; run `make bug-ledger`", e.ID)
		}
	}
	if strings.Count(page, "\n### BF-") != len(l.Entries) {
		t.Errorf("the page has %d entry sections and the JSON ledger has %d; run `make bug-ledger`", strings.Count(page, "\n### BF-"), len(l.Entries))
	}
}

// Fixed-ahead entries are the commitment that PiG's difference from Pi ends when Pi fixes the bug, so each divergence they name must still be recorded.
func TestBugLedgerDivergencesAreRecorded(t *testing.T) {
	l, _ := readBugLedger(t)
	ledger, err := os.ReadFile("../../docs/parity/DIVERGENCES.md")
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range l.Entries {
		if e.Divergence != "" && !strings.Contains(string(ledger), "## "+e.Divergence+" ") {
			t.Errorf("%s names %s, which docs/parity/DIVERGENCES.md does not record", e.ID, e.Divergence)
		}
	}
}

// Every divergence the ledger accounts for is recorded, a divergence that fixes a Pi defect names an entry that exists, and no record that cites a Pi issue is listed as a deliberate difference.
func TestBugLedgerAccountsForEveryDivergence(t *testing.T) {
	l, _ := readBugLedger(t)
	data, err := os.ReadFile("../../docs/parity/DIVERGENCES.md")
	if err != nil {
		t.Fatal(err)
	}
	records := string(data)
	ids := map[string]bool{}
	for _, e := range l.Entries {
		ids[e.ID] = true
	}
	if len(l.Divergences) == 0 {
		t.Fatal("the ledger accounts for no divergence; run `make bug-ledger`")
	}
	piIssue := regexp.MustCompile(`(?m)^## (D\d+) .*\((?:Pi|pi-mono) #\d+\)`)
	cited := map[string]bool{}
	for _, m := range piIssue.FindAllStringSubmatch(records, -1) {
		cited[m[1]] = true
	}
	for _, d := range l.Divergences {
		if !strings.Contains(records, "## "+d.ID+" ") {
			t.Errorf("the ledger accounts for %s, which docs/parity/DIVERGENCES.md does not record", d.ID)
		}
		if d.Entry != "" && !ids[d.Entry] {
			t.Errorf("%s names the entry %s, which the ledger does not have", d.ID, d.Entry)
		}
		if d.Entry == "" && cited[d.ID] {
			t.Errorf("%s cites a Pi issue in its title but the ledger lists it as a deliberate difference", d.ID)
		}
	}
}
